package com.ianblk.zianmobs;
import java.util.*;
import com.google.gson.*;
import com.ianblk.zianmobs.core.AtomicJson;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.*;
import net.minecraft.world.item.ItemStack;
final class CompanionUpgradeSmoke {
 static void check(boolean value,String message){if(!value)throw new IllegalStateException(message);}
 static void denied(Runnable action,String message){boolean no=false;try{action.run();}catch(IllegalArgumentException expected){no=true;}check(no,message);}
 static void run(ServerPlayer p,Companions s)throws Exception {
  CompanionVitalitySmoke.run(s);s.store(p.getUUID(),false);String id="gift";s.grant(p.getUUID(),id,Long.MAX_VALUE);var base=s.config(id);check(base.reviveSeconds()==600&&base.supportDuration()==15&&base.supportCooldown()==90,"New baseline balance incorrect");
  String diamond="shadow_shadow_diamond_1a";var item=CompanionUpgrades.ITEMS.get(diamond).get();var slot=p.getInventory().getItem(8).copy();
  try {
   p.getInventory().setItem(8,ItemStack.EMPTY);denied(()->s.upgrade(p,id,diamond),"Missing material accepted");
   p.getInventory().setItem(8,new ItemStack(item,8));s.summon(p,id);denied(()->s.upgrade(p,id,diamond),"Active companion upgraded");s.store(p.getUUID(),false);
   s.summon(p,id);p.removeAllEffects();p.setHealth(5);s.support(s.activeEntity(p.getUUID()),p);s.store(p.getUUID(),false);
   var state=s.life(p.getUUID(),id);long support=state.supportAt(),attack=state.attackAt();check(support==s.now()+90000,"Upgrade timer test did not start actual support cooldown");
   var view=s.snapshot(p,"companion_upgrades",id,"");var values=view.getAsJsonObject("values");values.addProperty("material",diamond);var token=UUID.fromString(view.get("token").getAsString());s.action(p,new MobsNetwork.PetAction(token,"upgrade",values.toString()));check(p.getInventory().getItem(8).getCount()==7&&s.upgrades(p.getUUID(),id).health()==2,"Material consumption or upgrade failed");var retained=s.upgradeView(p,id,diamond,"Mejora aplicada.");check(retained.getAsJsonObject("values").get("material").getAsString().equals(diamond)&&retained.getAsJsonObject("values").get("health").getAsString().contains("nivel 2/10"),"Upgrade response reset material or stats");java.nio.file.Files.writeString(java.nio.file.Path.of(System.getProperty("zianmobs.clientFixtures")).resolve("upgrade_response.json"),retained.toString());s.action(p,new MobsNetwork.PetAction(token,"upgrade",values.toString()));check(p.getInventory().getItem(8).getCount()==7,"Replayed upgrade consumed another item");
   for(int n=0;n<4;n++)s.upgrade(p,id,diamond);var upgraded=s.effective(p.getUUID(),id);check(upgraded.maxHealth()==2*base.maxHealth()&&upgraded.armor()==2*base.armor()&&upgraded.attackDamage()==2*base.attackDamage(),"Stats do not stop at double base");check(upgraded.supportDuration()==30&&upgraded.supportCooldown()==45&&upgraded.reviveSeconds()==300,"Maximum support/revival upgrades incorrect");check(s.life(p.getUUID(),id).supportAt()==support&&s.life(p.getUUID(),id).attackAt()==attack,"Upgrade reset persisted deadlines");int remaining=p.getInventory().getItem(8).getCount();denied(()->s.upgrade(p,id,diamond),"Maximum upgraded again");check(p.getInventory().getItem(8).getCount()==remaining,"Capped improvement consumed material");
   check(s.upgrades(p.getUUID(),"kit").equals(CompanionUpgrades.Levels.ZERO),"Upgrade leaked to another companion");check(s.upgrades(UUID.randomUUID(),id).equals(CompanionUpgrades.Levels.ZERO),"Upgrade leaked to another owner");var roundtrip=Companions.readData(s.file);check(roundtrip.owners().get(p.getUUID()).upgrades().get(id).equals(s.upgrades(p.getUUID(),id)),"Upgrade not persisted");
   s.summon(p,id);var pet=s.activeEntity(p.getUUID());check(pet.getMaxHealth()==72&&pet.getAttributeValue(net.minecraft.world.entity.ai.attributes.Attributes.ARMOR)==12,"Upgraded entity attributes wrong");pet.hurt(p.damageSources().genericKill(),10000);check(s.life(p.getUUID(),id).reviveAt()==s.now()+300000,"Upgraded revival deadline incorrect");denied(()->s.upgrade(p,id,"shadow_infested_egg_0a"),"Dead companion can bypass revival by upgrading");
   var legacy=new Gson().toJsonTree(s.data).getAsJsonObject();legacy.addProperty("schema",2);for(var entry:legacy.getAsJsonObject("settings").entrySet()){var row=entry.getValue().getAsJsonObject();row.addProperty("maxHealth",row.get("maxHealth").getAsDouble()/1.5);row.addProperty("armor",row.get("armor").getAsDouble()/1.5);row.addProperty("reviveSeconds",300);row.addProperty("supportCooldown",45);row.addProperty("supportDuration",30);}for(var entry:legacy.getAsJsonObject("owners").entrySet())entry.getValue().getAsJsonObject().remove("upgrades");var path=s.file.resolveSibling("shadow-migration-smoke.json");AtomicJson.write(path,legacy);var migrated=Companions.readData(path);check(migrated.schema()==4&&migrated.settings().get(id).reviveSeconds()==600&&migrated.settings().get(id).supportCooldown()==90&&migrated.settings().get(id).supportDuration()==15,"Old balance was not migrated once");check(migrated.owners().get(p.getUUID()).pets().equals(s.data.owners().get(p.getUUID()).pets())&&migrated.owners().get(p.getUUID()).grants().equals(s.data.owners().get(p.getUUID()).grants()),"Migration lost health, clocks or grants");AtomicJson.write(path,migrated);check(Companions.readData(path).equals(migrated),"Reload doubled migrated balance again");check(java.nio.file.Files.exists(path.resolveSibling(path.getFileName()+".before-shadow-upgrades.json")),"Migration backup missing");
   s.grant(p.getUUID(),id,0);denied(()->s.upgrade(p,id,diamond),"Revoked companion can upgrade");
   String perMaterial="cubee_lush";s.grant(p.getUUID(),perMaterial,Long.MAX_VALUE);for(var material:CompanionUpgrades.CATALOG){p.getInventory().setItem(8,new ItemStack(CompanionUpgrades.ITEMS.get(material.id()).get(),1));s.upgrade(p,perMaterial,material.id());check(p.getInventory().getItem(8).isEmpty(),"Material failed to consume: "+material.id());}check(s.upgrades(p.getUUID(),perMaterial).equals(new CompanionUpgrades.Levels(6,6,6,6,6,6)),"Individual materials raised incorrect stats");

   // Native hostile retaliation after accepted damage, without attracting unrelated mobs.
   s.grant(p.getUUID(),"clank",Long.MAX_VALUE);s.summon(p,"clank");pet=s.activeEntity(p.getUUID());var enemy=EntityType.ZOMBIE.create(p.serverLevel());enemy.moveTo(p.getX()+4,p.getY(),p.getZ());p.serverLevel().addFreshEntity(enemy);var other=EntityType.ZOMBIE.create(p.serverLevel());other.moveTo(p.getX()+5,p.getY(),p.getZ());p.serverLevel().addFreshEntity(other);p.setLastHurtMob(enemy);s.attack(pet,p);check(enemy.getTarget()==pet&&other.getTarget()!=pet,"Hostile retaliation missing or unrelated mob attracted");float hp=pet.getHealth();pet.invulnerableTime=0;check(enemy.doHurtTarget(pet)&&pet.getHealth()<hp,"Native mob cannot hurt companion");s.store(p.getUUID(),false);enemy.discard();other.discard();p.setLastHurtMob(null);
   // A fresh pet has no attack cooldown from the preceding retaliation check.
   s.grant(p.getUUID(),"ghost",Long.MAX_VALUE);s.summon(p,"ghost");pet=s.activeEntity(p.getUUID());var immune=EntityType.ZOMBIE.create(p.serverLevel());immune.moveTo(p.getX()+4,p.getY(),p.getZ());immune.setInvulnerable(true);p.serverLevel().addFreshEntity(immune);p.setLastHurtMob(immune);s.attack(pet,p);check(immune.getTarget()!=pet,"Rejected damage forced hostile retaliation");s.store(p.getUUID(),false);immune.discard();p.setLastHurtMob(null);

   java.nio.file.Files.writeString(java.nio.file.Path.of(System.getProperty("zianmobs.clientFixtures")).resolve("companion_upgrades.json"),view.toString());
  }finally {s.store(p.getUUID(),false);p.getInventory().setItem(8,slot);}
 }
}
